window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3fef587d8fb0559d"]={"versions": [{"id": "FIG-3fef587d8fb0559d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>agingAllowed : Boolean</code>: Steuert, ob das Event nach fehlerfreien Zyklen verlernt (Aging) werden darf.\n</li><li><code>clearEventBehavior : DiagnosticClearEventBehaviorEnum [0..1]</code>: Definiert das Verhalten des Event-Status beim Löschen via UDS-Service 0x14.\n</li><li><code>eventClearAllowed : DiagnosticEventClearAllowedEnum [0..1]</code>: Regelt die Löschbarkeit des Events.\n</li><li><code>eventKind : DiagnosticEventKindEnum</code>: Unterscheidet z. B. zwischen SW-C- und BSW-Events (<code>BSW</code> vs. <code>SWC</code>).\n</li><li><code>prestorageFreezeFrame : Boolean</code>: Aktiviert das Vorab-Einfrieren von Freeze-Frame-Daten vor endgültiger Fehlerqualifizierung.\n</li><li><code>«atpVariation» + eventFailureCycleCounterThreshold : PositiveInteger [0..1]</code>: Variabler Schwellwert der Zyklen mit Fehlereintritt bis zur Bestätigung des Fehlers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>automaticEnd : Boolean</code>: Zyklus wird bei erneutem Start des gleichen Zyklus automatisch beendet.\n</li><li><code>cycleAutostart : Boolean</code>: Automatischer Start des Betriebszyklus bei ECU-Initialisierung.\n</li><li><code>cycleStatusStorage : Boolean</code>: NVRAM-persistente Speicherung des Zyklus-Status über Spannungsunterbrechungen hinweg.\n</li><li><code>type : DiagnosticOperationCycleTypeEnum</code>: Zyklusart (z. B. <code>IGNITION</code>, <code>OBD_DRIVING_CYCLE</code>, <code>WARMUP</code>, <code>TIME</code>, <code>POWER</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [1]</code>: Unidirektionale Referenz auf exakt ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [1]</code>: Unidirektionale Referenz auf exakt einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-00146f3b5b8b1d77", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>agingAllowed : Boolean</code>: Steuert, ob das Event nach fehlerfreien Zyklen verlernt (Aging) werden darf.\n</li><li><code>clearEventBehavior : DiagnosticClearEventBehaviorEnum [0..1]</code>: Definiert das Verhalten des Event-Status beim Löschen via UDS-Service 0x14.\n</li><li><code>eventClearAllowed : DiagnosticEventClearAllowedEnum [0..1]</code>: Regelt die Löschbarkeit des Events.\n</li><li><code>eventKind : DiagnosticEventKindEnum</code>: Unterscheidet z. B. zwischen SW-C- und BSW-Events (<code>BSW</code> vs. <code>SWC</code>).\n</li><li><code>prestorageFreezeFrame : Boolean</code>: Aktiviert das Vorab-Einfrieren von Freeze-Frame-Daten vor endgültiger Fehlerqualifizierung.\n</li><li><code>recoverableInSameOperationCycle : Boolean [0..1]</code>: Bestimmt, ob ein als fehlerhaft gewertetes Event innerhalb desselben Betriebszyklus wieder in den Gut-Zustand übergehen kann.\n</li><li><code>«atpVariation» + eventFailureCycleCounterThreshold : PositiveInteger [0..1]</code>: Variabler Schwellwert der Zyklen mit Fehlereintritt bis zur Bestätigung des Fehlers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>automaticEnd : Boolean</code>: Zyklus wird bei erneutem Start des gleichen Zyklus automatisch beendet.\n</li><li><code>cycleAutostart : Boolean</code>: Automatischer Start des Betriebszyklus bei ECU-Initialisierung.\n</li><li><code>cycleStatusStorage : Boolean</code>: NVRAM-persistente Speicherung des Zyklus-Status über Spannungsunterbrechungen hinweg.\n</li><li><code>type : DiagnosticOperationCycleTypeEnum</code>: Zyklusart.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycleTypeEnum</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Enumeration zur Spezifikation des Zyklustyps.\n</li><li><strong>Literale:</strong> <code>ignition</code>, <code>obdDrivingCycle</code>, <code>power</code>, <code>time</code>, <code>warmup</code>, <code>other</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [1]</code>: Unidirektionale Referenz auf exakt ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [1]</code>: Unidirektionale Referenz auf exakt einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5c2a069179907f03", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>clearEventBehavior : DiagnosticClearEventBehaviorEnum [0..1]</code>: Definiert das Verhalten des Event-Status beim Löschen via UDS-Service 0x14.\n</li><li><code>eventClearAllowed : DiagnosticEventClearAllowedEnum [0..1]</code>: Regelt die Löschbarkeit des Events.\n</li><li><code>eventKind : DiagnosticEventKindEnum</code>: Unterscheidet z. B. zwischen SW-C- und BSW-Events (<code>BSW</code> vs. <code>SWC</code>).\n</li><li><code>prestorageFreezeFrame : Boolean</code>: Aktiviert das Vorab-Einfrieren von Freeze-Frame-Daten vor endgültiger Fehlerqualifizierung.\n</li><li><code>prestoredFreezeframeStoredInNvm : Boolean [0..1]</code>: Gibt an, ob vorab eingefrorene Freeze-Frames im NVRAM gesichert werden.\n</li><li><code>recoverableInSameOperationCycle : Boolean [0..1]</code>: Bestimmt, ob ein als fehlerhaft gewertetes Event innerhalb desselben Betriebszyklus wieder in den Gut-Zustand übergehen kann.\n</li><li><code>«atpVariation» + eventFailureCycleCounterThreshold : PositiveInteger [0..1]</code>: Variabler Schwellwert der Zyklen mit Fehlereintritt bis zur Bestätigung des Fehlers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>automaticEnd : Boolean</code>: Zyklus wird bei erneutem Start des gleichen Zyklus automatisch beendet.\n</li><li><code>cycleAutostart : Boolean</code>: Automatischer Start des Betriebszyklus bei ECU-Initialisierung.\n</li><li><code>cycleStatusStorage : Boolean</code>: NVRAM-persistente Speicherung des Zyklus-Status über Spannungsunterbrechungen hinweg.\n</li><li><code>type : DiagnosticOperationCycleTypeEnum</code>: Zyklusart.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycleTypeEnum</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Enumeration zur Spezifikation des Zyklustyps.\n</li><li><strong>Literale:</strong> <code>ignition</code>, <code>obdDrivingCycle</code>, <code>warmup</code>, <code>other</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [1]</code>: Unidirektionale Referenz auf exakt ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [1]</code>: Unidirektionale Referenz auf exakt einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4033674f5035523f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>clearEventBehavior : DiagnosticClearEventBehaviorEnum [0..1]</code>: Definiert das Verhalten des Event-Status beim Löschen via UDS-Service 0x14.\n</li><li><code>eventClearAllowed : DiagnosticEventClearAllowedEnum [0..1]</code>: Regelt die Löschbarkeit des Events.\n</li><li><code>eventKind : DiagnosticEventKindEnum</code>: Unterscheidet z. B. zwischen SW-C- und BSW-Events (<code>BSW</code> vs. <code>SWC</code>).\n</li><li><code>prestorageFreezeFrame : Boolean</code>: Aktiviert das Vorab-Einfrieren von Freeze-Frame-Daten vor endgültiger Fehlerqualifizierung.\n</li><li><code>prestoredFreezeframeStoredInNvm : Boolean [0..1]</code>: Gibt an, ob vorab eingefrorene Freeze-Frames im NVRAM gesichert werden.\n</li><li><code>recoverableInSameOperationCycle : Boolean [0..1]</code>: Bestimmt, ob ein als fehlerhaft gewertetes Event innerhalb desselben Betriebszyklus wieder in den Gut-Zustand übergehen kann.\n</li><li><code>«atpVariation» + eventFailureCycleCounterThreshold : PositiveInteger [0..1]</code>: Variabler Schwellwert der Zyklen mit Fehlereintritt bis zur Bestätigung des Fehlers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>automaticEnd : Boolean</code>: Zyklus wird bei erneutem Start des gleichen Zyklus automatisch beendet.\n</li><li><code>cycleAutostart : Boolean</code>: Automatischer Start des Betriebszyklus bei ECU-Initialisierung.\n</li><li><code>cycleStatusStorage : Boolean</code>: NVRAM-persistente Speicherung des Zyklus-Status über Spannungsunterbrechungen hinweg.\n</li><li><code>type : DiagnosticOperationCycleTypeEnum</code>: Zyklusart.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycleTypeEnum</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Enumeration zur Spezifikation des Zyklustyps.\n</li><li><strong>Literale:</strong> <code>ignition</code>, <code>obdDrivingCycle</code>, <code>warmup</code>, <code>other</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [1]</code>: Unidirektionale Referenz auf exakt ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [1]</code>: Unidirektionale Referenz auf exakt einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-47e48da17a5aef8b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>associatedEventIdentification : PositiveInteger [0..1]</code>: Kennung des assoziierten Diagnose-Events.\n</li><li><code>clearEventAllowedBehavior : DiagnosticClearEventAllowedBehaviorEnum [0..1]</code>: Definiert das Verhalten hinsichtlich der Zulässigkeit des Löschens des Event-Status.\n</li><li><code>eventClearAllowed : DiagnosticEventClearAllowedEnum [0..1]</code>: Regelt die Löschbarkeit des Events.\n</li><li><code>eventKind : DiagnosticEventKindEnum [0..1]</code>: Unterscheidet z. B. zwischen SW-C- und BSW-Events (<code>BSW</code> vs. <code>SWC</code>).\n</li><li><code>prestorageFreezeFrame : Boolean [0..1]</code>: Steuert das Vorab-Einfrieren von Freeze-Frame-Daten vor endgültiger Fehlerqualifizierung.\n</li><li><code>prestoredFreezeframeStoredInNvm : Boolean [0..1]</code>: Gibt an, ob vorab eingefrorene Freeze-Frames im NVRAM gesichert werden.\n</li><li><code>recoverableInSameOperationCycle : Boolean [0..1]</code>: Bestimmt, ob ein als fehlerhaft gewertetes Event innerhalb desselben Betriebszyklus wieder in den Gut-Zustand übergehen kann.\n</li><li><code>«atpVariation» + confirmationThreshold : PositiveInteger [0..1]</code>: Variabler Schwellwert der Zyklen mit Fehlereintritt bis zur Bestätigung des Fehlers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>automaticEnd : Boolean [0..1]</code>: Zyklus wird bei erneutem Start des gleichen Zyklus automatisch beendet.\n</li><li><code>cycleStatusStorage : Boolean [0..1]</code>: NVRAM-persistente Speicherung des Zyklus-Status über Spannungsunterbrechungen hinweg.\n</li><li><code>type : DiagnosticOperationCycleTypeEnum [0..1]</code>: Zyklusart.\n</li></ul>\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycleTypeEnum</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Enumeration zur Spezifikation des Zyklustyps.\n</li><li><strong>Literale:</strong> <code>ignition</code>, <code>obdDrivingCycle</code>, <code>warmup</code>, <code>other</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [0..1]</code>: Unidirektionale Referenz auf optional ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [0..1]</code>: Unidirektionale Referenz auf optional einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3c6e0918bd5c5283", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [0..1]</code>: Unidirektionale Referenz auf optional ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [0..1]</code>: Unidirektionale Referenz auf optional einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-891097406fb87dd7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [0..1]</code>: Unidirektionale Referenz auf optional ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [0..1]</code>: Unidirektionale Referenz auf optional einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-000372790bd234bb", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [0..1]</code>: Unidirektionale Referenz auf optional ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [0..1]</code>: Unidirektionale Referenz auf optional einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7b4a13f5d7a1c761", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [0..1]</code>: Unidirektionale Referenz auf optional ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+operationCycle}}$ <code>DiagnosticOperationCycle [0..1]</code>: Unidirektionale Referenz auf optional einen Betriebszyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8f0a3eeb071049b1", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm auf M2-Metamodellebene (AUTOSAR Diagnostic Extract Template, DEXT; R4.2.2).\n</li><li><strong>Architektur-Kontext:</strong> Formalisiert den OEM-zu-Tier-1-Datenaustausch für das Diagnose-Subsystem. Das Diagramm spezifiziert die Bindung von Diagnose-Ereignissen (<code>DiagnosticEvent</code>) an Betriebszyklen (<code>DiagnosticOperationCycle</code>), welche im BSW-Modul <code>Dem</code> (Diagnostic Event Manager) die zeitliche Basis für Entprellung, Status-Byte-Übergänge (ISO 14229-1), Bestätigungslogik (<code>ConfirmedDTC</code>) und Aging bilden (Ref: RS_DEXT_00024, RS_DEXT_00054, TPS_DEXT_01086).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticEventToOperationCycleMapping</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Konkretes Mapping-Element, spezialisiert die abstrakte Metaklasse <code>DiagnosticMapping</code>.\n</li><li><strong>Semantik:</strong> Assoziationsentität zur Zuweisung des auswertungsrelevanten Betriebszyklus zu einem spezifischen Diagnose-Event.\n</li></ul>\n</li><li><strong><code>DiagnosticEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemEventParameter</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ / Vererbung:</strong> Spezialisiert <code>DiagnosticCommonElement</code>. Entspricht im BSW-Modell dem <code>DemOperationCycle</code>.\n</li></ul>\n</li><li><strong>Beziehungen und Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticEvent}}$ <code>DiagnosticEvent [0..1]</code>: Unidirektionale Referenz auf optional ein Diagnose-Ereignis.\n</li><li><code>DiagnosticEventToOperationCycleMapping</code> $\\xrightarrow{\\text{+diagnosticOperationCycle}}$ <code>DiagnosticOperationCycle [0..1]</code>: Unidirektionale Referenz auf optional einen Betriebszyklus mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Metamodell definiert das Diagramm die Konfigurationsbasis für folgende BSW-Laufzeitmechanismen im <code>Dem</code>:</p>\n<ol class=\"fig-list\"><li><strong>Zyklussteuerung:</strong> Externe Trigger (z. B. <code>BswM</code> oder <code>EcuM</code>) schalten Zyklen über die API <code>Dem_SetOperationCycleState(OperationCycleId, CycleState)</code> (<code>DEM_CYCLE_STATE_START</code> / <code>DEM_CYCLE_STATE_END</code>).\n</li><li><strong>Status-Reset:</strong> Mit dem Neustart des verknüpften <code>DiagnosticOperationCycle</code> setzt der <code>Dem</code> für das zugeordnete <code>DiagnosticEvent</code> die UDS-Statusbits 1 (<code>testFailedThisOperationCycle</code>) und 6 (<code>testNotCompletedThisOperationCycle</code>) zurück.\n</li><li><strong>Fehlerqualifizierung:</strong> Registriert das Event während des aktiven Zyklus einen Fehler (<code>DEM_EVENT_STATUS_FAILED</code>), inkrementiert der <code>Dem</code> den zyklenbasierten Fehlerzähler. Erreicht dieser den Schwellwert <code>eventFailureCycleCounterThreshold</code>, wechselt UDS-Statusbit 3 (<code>confirmedDTC</code>) auf <code>1</code>.\n</li><li><strong>Aging-Prozess:</strong> Sofern <code>agingAllowed == TRUE</code>, dekrementiert bzw. inkrementiert ein fehlerfreier Zyklus den Aging-Zähler zur Freigabe des Fehlerspeichereintrags.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (Dem-Generierung):</strong>\n<ul class=\"fig-list\"><li>Das Mapping transformiert im BSW-Generierungsprozess direkt in die ECUC-Parameterstruktur <code>DemEventParameter</code> → <code>DemOperationCycleRef</code> → <code>DemOperationCycle</code>.\n</li><li>Jedes <code>DiagnosticEvent</code> benötigt zwingend (<code>[1]</code>) eine gültige Zykluszuordnung gemäß TPS_DEXT_01086; ein fehlendes Mapping führt zu unvollständigen Dem-Statusautomaten und ungültiger BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong>\n<ul class=\"fig-list\"><li><code>eventFailureCycleCounterThreshold</code> unterliegt der AUTOSAR-Variantenschnittstelle (<code>atpVariation</code>). Dies erlaubt die Anpassung der Bestätigungszyklen (z. B. 1-Cycle vs. 2-Cycle-Qualifier) abhängig von Emissionsmärkten (CARB, EPA, EU-OBD) über Variantencodes (Post-Build oder Pre-Compile).\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>cycleAutostart == FALSE</code>, muss die Applikation bzw. der Modus-Manager (<code>BswM</code>) den Zyklus explizit per API starten, da andernfalls keine Fehlerauswertung und kein Bit-Aging für das gemappte Event stattfinden kann.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3fef587d8fb0559d", "to": "FIG-00146f3b5b8b1d77", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticEvent</code>: Attribut <code>recoverableInSameOperationCycle : Boolean [0..1]</code> hinzugefügt.\n</li><li><code>DiagnosticOperationCycleTypeEnum</code>: Enumeration mit den Literalen <code>ignition</code>, <code>obdDrivingCycle</code>, <code>power</code>, <code>time</code>, <code>warmup</code> und <code>other</code> im Diagramm ergänzt.\n</li></ul>"}, {"from": "FIG-00146f3b5b8b1d77", "to": "FIG-5c2a069179907f03", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticEvent</code>: Attribut <code>agingAllowed : Boolean</code> entfernt.\n</li><li><code>DiagnosticEvent</code>: Attribut <code>prestoredFreezeframeStoredInNvm : Boolean [0..1]</code> hinzugefügt.\n</li><li><code>DiagnosticOperationCycleTypeEnum</code>: Literale <code>power</code> und <code>time</code> entfernt (verbleibend: <code>ignition</code>, <code>obdDrivingCycle</code>, <code>warmup</code>, <code>other</code>).\n</li></ul>"}, {"from": "FIG-5c2a069179907f03", "to": "FIG-4033674f5035523f", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>DiagnosticOperationCycleTypeEnum</code>: Vertikale Positionierung bzw. Abstand der Enumerationsbox im Diagrammlayout nach unten verschoben.\n</li></ul>"}, {"from": "FIG-4033674f5035523f", "to": "FIG-47e48da17a5aef8b", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticEventToOperationCycleMapping</code>: Multiplizitäten der Assoziationsenden <code>+diagnosticEvent</code> und <code>+operationCycle</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><code>DiagnosticEvent</code>: Attribut <code>associatedEventIdentification : PositiveInteger [0..1]</code> hinzugefügt.\n</li><li><code>DiagnosticEvent</code>: Attribut <code>clearEventBehavior : DiagnosticClearEventBehaviorEnum [0..1]</code> ersetzt durch <code>clearEventAllowedBehavior : DiagnosticClearEventAllowedBehaviorEnum [0..1]</code>.\n</li><li><code>DiagnosticEvent</code>: Multiplizität der Attribute <code>eventKind</code> und <code>prestorageFreezeFrame</code> von <code>1</code> auf <code>[0..1]</code> geändert.\n</li><li><code>DiagnosticEvent</code>: «atpVariation»-Attribut <code>eventFailureCycleCounterThreshold</code> umbenannt in <code>confirmationThreshold : PositiveInteger [0..1]</code>.\n</li><li><code>DiagnosticOperationCycle</code>: Attribut <code>cycleAutostart : Boolean</code> entfernt.\n</li><li><code>DiagnosticOperationCycle</code>: Multiplizität der Attribute <code>automaticEnd</code>, <code>cycleStatusStorage</code> und <code>type</code> von <code>1</code> auf <code>[0..1]</code> geändert.\n</li></ul>"}, {"from": "FIG-47e48da17a5aef8b", "to": "FIG-3c6e0918bd5c5283", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticEvent</code>: Sämtliche Attribute (<code>associatedEventIdentification</code>, <code>clearEventAllowedBehavior</code>, <code>eventClearAllowed</code>, <code>eventKind</code>, <code>prestorageFreezeFrame</code>, <code>prestoredFreezeframeStoredInNvm</code>, <code>recoverableInSameOperationCycle</code>, <code>confirmationThreshold</code>) aus der Diagrammdarstellung entfernt.\n</li><li><code>DiagnosticOperationCycle</code>: Sämtliche Attribute (<code>automaticEnd</code>, <code>cycleStatusStorage</code>, <code>type</code>) aus der Diagrammdarstellung entfernt.\n</li><li><code>DiagnosticOperationCycleTypeEnum</code>: Enumeration vollständig aus dem Diagramm entfernt.\n</li><li>Diagrammlayout: Anordnung der Klassen von vertikaler Baumstruktur auf horizontale Sequenz (<code>DiagnosticEvent</code> – <code>DiagnosticEventToOperationCycleMapping</code> – <code>DiagnosticOperationCycle</code>) umgestellt.\n</li></ul>"}, {"from": "FIG-3c6e0918bd5c5283", "to": "FIG-891097406fb87dd7", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-891097406fb87dd7", "to": "FIG-000372790bd234bb", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-000372790bd234bb", "to": "FIG-7b4a13f5d7a1c761", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7b4a13f5d7a1c761", "to": "FIG-8f0a3eeb071049b1", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Assoziation zu <code>DiagnosticOperationCycle</code>:</strong>\n<ul class=\"fig-list\"><li>Rollenbezeichnung von <code>+operationCycle</code> zu <code>+diagnosticOperationCycle</code> umbenannt.\n</li><li>Stereotypen <code>«atpVariation,atpSplitable»</code> an der Referenz ergänzt.\n</li></ul>\n</li></ul>"}]};
